import styled from "styled-components";

export const InputImageContainer = styled.div<{image: any}>`
    width:7rem;
    height:6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background-image: url(${({image}) => image});
    background-position: center;

    

    input{
        font-size: 0.75rem;
        font-weight: 400; 
        border: 0;
        width: 100%;
        height:100%;
        border: 1px dashed #000;
        
    }
`
